class FeedForward(nn.Module):
    """前馈神经网络（Position-wise FFN）"""
    def init(self, dmodel, dff=None, dropout=0.1):
        super().init()
        dff = dff or 4  dmodel  # 默认4倍扩展
        self.net = nn.Sequential(
            nn.Linear(dmodel, dff),
            nn.GELU(),       # 现代模型多用GELU替代ReLU
            nn.Dropout(dropout),
            nn.Linear(dff, dmodel),
            nn.Dropout(dropout),
        )

    def forward(self, x):
        return self.net(x)

def initweights(self):
        for p in self.parameters():
            if p.dim() > 1:
                nn.init.xavieruniform(p)

    def encode(self, src, srcmask=None):
        x = self.posenc(self.srcembed(src)  math.sqrt(self.dmodel))
        for layer in self.encoderlayers:
            x = layer(x, srcmask)
        return x

    def decode(self, tgt, encoutput, srcmask=None, tgtmask=None):
        x = self.posenc(self.tgtembed(tgt)  math.sqrt(self.dmodel))
        for layer in self.decoderlayers:
            x = layer(x, encoutput, srcmask, tgtmask)
        return self.outputnorm(x)

def forward(self, src, tgt, srcmask=None, tgtmask=None):
        encoutput = self.encode(src, srcmask)
        decoutput = self.decode(tgt, encoutput, srcmask, tgtmask)
        logits = self.outputproj(decoutput)
        return logits

    def makesrcmask(self, src):
        """源序列padding掩码"""
        return (src != self.padidx).unsqueeze(1).unsqueeze(2)

class RewardModel(nn.Module):
    """奖励模型：输入(问题+回答)，输出标量分数"""
    def init(self, basemodel):
        super().init()
        self.basemodel = basemodel
        self.valuehead = nn.Linear(basemodel.config.hiddensize, 1)

    def forward(self, inputids, attentionmask):
        # 取最后一个token的隐状态
        outputs = self.basemodel(inputids=inputids, attentionmask=attentionmask)
        lasthidden = outputs.lasthiddenstate[:, -1, :]  # (batch, hidden)
        reward = self.valuehead(lasthidden)  # (batch, 1)
        return reward.squeeze(-1)

def rewardmodelloss(chosenscores, rejectedscores, margin=0):
    """Bradley-Terry偏好模型损失"""
    # P(chosen > rejected) = sigmoid(rchosen - rrejected)
    loss = -torch.log(torch.sigmoid(chosenscores - rejectedscores - margin))
    return loss.mean()

def multiqueryreranking(question, llm, vectorstore, reranker, topk=5):
    """
    Multi-Query：让LLM生成多个视角的查询，扩大召回
    """
    # LLM生成多个改写查询
    prompt = f"""请从不同角度生成3个与以下问题相关的搜索查询：
    原始问题：{question}
    查询1/查询2/查询3："""

    queries = llm.generate(prompt).strip().split('\n')
    allqueries = [question] + queries  # 包含原始查询

    # 对每个查询检索并去重
    allcandidates = {}
    for q in allqueries:
        candidates = vectorstore.similaritysearch(q, k=20)
        for doc in candidates:
            if doc.pagecontent not in allcandidates:
                allcandidates[doc.pagecontent] = doc

    # 用原始问题对候选文档重排序
    pairs = [[question, text] for text in allcandidates.keys()]
    scores = reranker.predict(pairs)

def computefaithfulness(answer, retrieveddocs):
    """
    手动计算忠实度：回答中的每个断言是否有文档支撑
    """
    # Step 1: 从回答中提取断言
    claimsprompt = f"从以下回答中提取所有事实断言：\n{answer}"
    claims = llm.generate(claimsprompt).split('\n')

    # Step 2: 检查每个断言是否有文档支撑
    supported = 0
    for claim in claims:
        for doc in retrieveddocs:
            verifyprompt = f"""以下断言是否被文档所支撑？
            断言：{claim}
            文档：{doc}
            回答YES或NO："""
            if "YES" in llm.generate(verifyprompt):
                supported += 1
                break

    return supported / len(claims) if claims else 0

def computecontextrelevance(question, retrieveddocs):
    """计算检索相关性：检索到的文档中与问题相关的比例"""
    relevant = 0
    for doc in retrieveddocs:
        judgeprompt = f"""以下文档是否与问题相关？
        问题：{question}
        文档：{doc.pagecontent[:500]}
        相关（YES/NO）："""
        if "YES" in llm.generate(judgeprompt):
            relevant += 1
    return relevant / len(retrieveddocs)

