def calculateportfolio(holdings: list) -> dict:
    """计算投资组合"""
    totalvalue = 0
    totalcost = 0
    for h in holdings:
        # 先获取当前价格
        pricedata = getstockprice(h["symbol"])
        if "error" not in pricedata:
            currentvalue = pricedata["price"]  h["shares"]
            costvalue = h["costbasis"]  h["shares"]
            totalvalue += currentvalue
            totalcost += costvalue

    return {
        "totalvalue": round(totalvalue, 2),
        "totalcost": round(totalcost, 2),
        "profitloss": round(totalvalue - totalcost, 2),
        "returnpct": round((totalvalue - totalcost) / totalcost  100, 2) if totalcost > 0 else 0
    }

