class ConversationSummarizer:
    """对话摘要压缩 - 用LLM总结历史对话，释放窗口空间"""

    def init(self, client, model="gpt-4", summarytrigger=3000):
        self.client = client
        self.model = model
        self.summarytrigger = summarytrigger  # 触发摘要的token阈值
        self.summary = ""  # 存储摘要

def shouldsummarize(self, messages: list) -> bool:
        """判断是否需要摘要压缩"""
        totaltokens = sum(len(m["content"]) // 2 for m in messages if m["role"] != "system")
        return totaltokens > self.summarytrigger

    def summarize(self, messages: list) -> str:
        """生成对话摘要"""
        # 提取需要摘要的消息（排除system消息）
        conversationtext = ""
        for msg in messages:
            if msg["role"] != "system":
                conversationtext += f"{msg['role']}: {msg['content']}\n"

response = self.client.chat.completions.create(
            model=self.model,
            messages=[
                {
                    "role": "system",
                    "content": (
                        "请将以下对话历史压缩为简洁的摘要，保留所有关键信息：\n"
                        "- 讨论的主要话题\n"
                        "- 做出的重要决定\n"
                        "- 提到的关键事实和数据\n"
                        "- 未解决的问题\n"
                    )
                },
                {"role": "user", "content": conversationtext}
            ]
        )

        self.summary = response.choices[0].message.content
        return self.summary

    def getcompressedmessages(self, messages: list) -> list:
        """获取压缩后的消息列表"""
        if not self.shouldsummarize(messages):
            return messages

def addentity(self, name: str, entitytype: str, properties: dict = None):
        """添加实体"""
        self.entities[name] = {
            "type": entitytype,
            "properties": properties or {}
        }

    def addrelation(self, subject: str, predicate: str, obj: str, properties: dict = None):
        """添加关系"""
        self.relations.append((subject, predicate, obj, properties or {}))

    def queryentity(self, name: str) -> dict:
        """查询实体及其所有关系"""
        if name not in self.entities:
            return {"error": f"实体 {name} 不存在"}

        entity = self.entities[name]
        related = []

# 查找与该实体相关的所有关系
        for s, p, o, props in self.relations:
            if s == name:
                related.append({"direction": "outgoing", "predicate": p, "target": o, "properties": props})
            elif o == name:
                related.append({"direction": "incoming", "predicate": p, "source": s, "properties": props})

        return {"entity": entity, "relations": related}

    def querypath(self, start: str, end: str, maxdepth: int = 3) -> list:
        """查询两个实体之间的路径（BFS）"""
        from collections import deque

        queue = deque([(start, [start])])
        visited = {start}

        while queue:
            current, path = queue.popleft()

            if current == end:
                return path

            if len(path) > maxdepth:
                continue

class Scratchpad:
    """工作记忆 - 存储当前任务的中间状态"""

    def init(self):
        self.state = {}        # 当前状态
        self.history = []      # 操作历史
        self.variables = {}    # 中间变量

    def set(self, key: str, value):
        """设置状态变量"""
        oldvalue = self.state.get(key)
        self.state[key] = value
        self.history.append({
            "action": "set",
            "key": key,
            "oldvalue": oldvalue,
            "newvalue": value
        })

    def get(self, key: str, default=None):
        """获取状态变量"""
        return self.state.get(key, default)

def getcontextstring(self) -> str:
        """将工作记忆格式化为可注入提示的字符串"""
        lines = ["[当前工作记忆状态]"]
        for key, value in self.state.items():
            lines.append(f"  {key}: {value}")
        return "\n".join(lines)

    def clear(self):
        """清空工作记忆（新任务开始时）"""
        self.state.clear()
        self.history.clear()
        self.variables.clear()

