===== EMA (Exponential Moving Average) =====
class ModelEMA:
    """模型参数的指数移动平均"""

    def init(self, model, decay=0.9999):
        self.decay = decay
        self.shadow = {}  # EMA参数
        self.backup = {}  # 用于验证时临时切换

        # 初始化EMA参数
        for name, param in model.namedparameters():
            if param.requiresgrad:
                self.shadow[name] = param.data.clone()

    def update(self, model):
        """更新EMA参数"""
        for name, param in model.namedparameters():
            if param.requiresgrad:
                newaverage = (1.0 - self.decay)  param.data + self.decay  self.shadow[name]
                self.shadow[name] = newaverage.clone()

def applyshadow(self, model):
        """将EMA参数应用到模型（用于验证/推理）"""
        for name, param in model.namedparameters():
            if param.requiresgrad:
                self.backup[name] = param.data
                param.data = self.shadow[name]

    def restore(self, model):
        """恢复原始参数"""
        for name, param in model.namedparameters():
            if param.requiresgrad:
                param.data = self.backup[name]
        self.backup = {}

