import torch

class DDPM:
    def init(self, T=1000, betastart=1e-4, betaend=0.02):
        self.T = T
        self.betas = torch.linspace(betastart, betaend, T)
        self.alphas = 1 - self.betas
        self.alphabars = torch.cumprod(self.alphas, dim=0)

    def qsample(self, x0, t, noise=None):
        """前向加噪"""
        if noise is None:
            noise = torch.randnlike(x0)
        sqrtab = self.alphabars[t].sqrt().view(-1, 1, 1, 1)
        sqrt1mab = (1 - self.alphabars[t]).sqrt().view(-1, 1, 1, 1)
        return sqrtab  x0 + sqrt1mab  noise, noise

    def trainstep(self, model, x0):
        t = torch.randint(0, self.T, (x0.size(0),))
        xt, noise = self.qsample(x0, t)
        prednoise = model(xt, t)
        return F.mseloss(prednoise, noise)

